// Scans public/models/*.glb and writes src/data/model-manifest.js.
//
// Why this exists: DishModel must know which .glb files are present WITHOUT
// fetching missing ones at runtime — browsers log every failed fetch as a
// console 404 that JavaScript cannot suppress. A build-time manifest lets
// the gate resolve 'missing' with zero network requests.
//
// Runs automatically via npm `predev` / `prebuild`. The generated file is
// committed so fresh clones work before their first `npm run dev`.
// NOTE (dev sessions): files dropped into public/models mid-session need a
// dev-server restart to enter the manifest (restart re-runs `predev`).
import { readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const modelsDir = join(root, 'public', 'models');
const outFile = join(root, 'src', 'data', 'model-manifest.js');

let urls = [];
try {
  urls = readdirSync(modelsDir)
    .filter((f) => f.toLowerCase().endsWith('.glb'))
    .sort()
    .map((f) => `/models/${f}`);
} catch {
  // No public/models dir yet — empty manifest, everything falls back.
}

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(
  outFile,
  `// AUTO-GENERATED by scripts/generate-model-manifest.mjs — do not edit.\n` +
    `// Regenerated on \`npm run dev\` / \`npm run build\` (predev/prebuild).\n` +
    `// Lists .glb assets present in public/models at generation time.\n` +
    `export const AVAILABLE_MODELS = ${JSON.stringify(urls, null, 2)};\n`
);
console.log(`[model-manifest] ${urls.length} model(s): ${urls.join(', ') || '(none — procedural fallbacks)'}`);
